// Extract raw JSON from LLM
const raw = $input.first().json.content.parts[0].text;

// Parse into array
let frames = JSON.parse(raw);

// Create a single output object
let output = {};

frames.forEach(f => {
  const index = f.frame; // 1..15
  output[`edit_instruction_${index}`] = f.edit_instruction;
  output[`description_${index}`] = f.description;
  output[`step_name_${index}`] = f.step_name;
  output[`generate_prompt_${index}`] = f.generate_prompt;
});

return [
  {
    json: output
  }
];

// Ensure this node runs once (Run Once for All Items)

// 1) Read all items produced by the earlier node that parsed the LLM
// Replace "Code in JavaScript1" with the exact node name if different
const itemsFromParser = $items("Code in JavaScript1");

// Convert node items to raw JSON frames
const allFrames = itemsFromParser.map(it => it.json);

// Safety check
if (!Array.isArray(allFrames) || allFrames.length === 0) {
  throw new Error("No frames found from Code in JavaScript1. Check upstream node.");
}

// 2) Find frame 1 (fall back to first item)
const frame1 = allFrames.find(f => Number(f.frame) === 1) || allFrames[0];

// 3) Return ONLY frame1 so the Generate-first-frame node receives a single clean object
return [
  {
    json: frame1
  }
];
